parameters.jsCode:
// R017-bis (2026-08-25): 'Guardar clasificación' es un nodo Postgres — su salida es el
// resultado del UPDATE, no la clasificación. Leer $json acá tomaba ese resultado casi vacío,
// perdiendo scope/intent/recommended_action antes de que la compuerta pudiera verlos. Se lee
// la clasificación real por referencia directa al nodo que la produjo (A0 en éxito, el nodo de
// respaldo en fallo — exactamente uno de los dos corrió en esta ejecución).
let c;
try {
  c = $('Clasificación de respaldo (fallo de parseo)').item.json;
} catch (e) {
  c = $('A0 · Clasificador').item.json;
  c = c.output || c;
}
// R023 (2026-08-27) — red de seguridad contra escalaciones innecesarias.
// Caso real: "buenas, me pasa el precio del rcv de mi carro?" clasificó
//   product=rcv_auto, intent=quote_request, confidence=0.85 ...y requires_human=true,
//   con escalation_reason "se requiere información adicional del vehículo".
// El IF ¿HUMAN_REQUIRED? lee ese campo como verdad absoluta, así que el cliente recibió
// "eso lo debe confirmar Nairobi" en vez de que Nai le pidiera la placa y cotizara.
// Pedirle datos al cliente es el trabajo del agente, no un motivo para molestar a Nairobi.
// Mismo principio que la compuerta (R017): no se confía en un solo campo del modelo.
const ACCIONES_QUE_RESUELVE_NAI = ['ask_information', 'quote', 'answer', 'conversational'];
const PRODUCTOS_VALIDOS = [
  'rcv_moto', 'rcv_auto', 'salud', 'embarazo', 'vida', 'hogar', 'funerario',
  'viaje', 'accidentes_personales',
];
const pidioHumano = /nairobi|human|persona|hablar con/i.test(
  `${c.escalation_reason || ''} ${c.intent || ''}`,
);
if (
  c.requires_human === true
  && !pidioHumano
  && c.urgency !== 'emergency'
  && ACCIONES_QUE_RESUELVE_NAI.includes(c.recommended_action)
  && PRODUCTOS_VALIDOS.includes(c.product)
) {
  c.requires_human = false;
  c.human_override_reason = `escalación anulada: ${c.recommended_action} sobre ${c.product} `
    + 'es algo que Nai resuelve sola (motivo original: '
    + `${c.escalation_reason || 'sin motivo'})`;
  c.escalation_reason = null;
}

// R026 (2026-08-27) — la baja confianza solo aplica al negocio.
// 'confidence' mide, por definicion del propio clasificador, que tan seguro esta
// de intent+product. Un mensaje personal o spam NO tiene producto, asi que puntua
// bajo siempre. Con el umbral aplicado a ciegas, todo mensaje ajeno al negocio se
// convertia en human_required y el cliente recibia "eso lo debe confirmar Nairobi".
// Caso real: un familiar mando un enlace de Facebook y recibio ese mensaje puente.
// Si el clasificador dice que no es del negocio, la duda se resuelve callando, no
// molestando a Nairobi.
const NO_ES_NEGOCIO = ['personal', 'spam'].includes(c.scope)
  || c.recommended_action === 'ignore';

if (NO_ES_NEGOCIO && c.urgency !== 'emergency') {
  c.requires_human = false;
  c.recommended_action = c.recommended_action === 'ignore' ? 'ignore' : 'conversational';
  c.escalation_reason = null;
  c.low_confidence_skipped = `scope=${c.scope}: la baja confianza no escala fuera del negocio`;
} else if ((c.confidence ?? 0) < 0.55) {
  c.requires_human = true;
  if (c.recommended_action !== 'emergency_protocol') c.recommended_action = 'human_required';
  c.escalation_reason = c.escalation_reason || 'low_confidence';
}
return [{ json: { ...c, chat_id: $('Entrada desde W1').item.json.chat_id, phone: $('Entrada desde W1').item.json.phone, conversation_id: $('Entrada desde W1').item.json.conversation_id, contact_id: $('Entrada desde W1').item.json.contact_id, message_text: $('Entrada desde W1').item.json.message_text, is_test: $('Entrada desde W1').item.json.is_test } }];

// ÚNICA fuente de verdad de a quién le responde Nai (R015, D014, R017).
// Si cambia la regla, se cambia acá y en ningún otro lado.
const cls = $('Forzar umbral de confianza').item.json;
const gate = $json;

// R017 — por qué no se confía en un solo campo:
// caso real (2026-08-24) "Buenas, necesito un seguro para mi carro" devolvió
//   intent=quote_request, product=rcv_auto, recommended_action=quote, confidence=0.95
//   ...y sin embargo scope='personal', contradiciéndose a sí mismo.
// Basta con que CUALQUIER señal indique negocio. El modelo puede fallar un campo;
// que falle los tres a la vez es mucho menos probable.
const ACCIONES_NEGOCIO = [
  'quote', 'register_claim', 'payment_information', 'schedule', 'emergency_protocol',
];
const INTENTS_NEGOCIO = [
  'quote_request', 'claim_report', 'payment_inquiry', 'policy_question',
  'appointment_request', 'renewal', 'cancellation', 'document_submission',
];

const isIgnore = cls.recommended_action === 'ignore';
// R021 (2026-08-26) — "hola buenas, quiero sacar el rcv de mi carro" clasificó
//   scope=personal, intent=document_submission, product=rcv_auto (confianza 0.95).
// El campo product fue el único correcto: el modelo identifica bien QUÉ seguro es
// incluso cuando se equivoca en el scope/intent. Se suma como cuarta señal.
const PRODUCTOS_VALIDOS = [
  'rcv_moto', 'rcv_auto', 'salud', 'embarazo', 'vida', 'hogar', 'funerario',
  'viaje', 'accidentes_personales',
];
const isBusiness =
  cls.scope === 'business'
  || ACCIONES_NEGOCIO.includes(cls.recommended_action)
  || INTENTS_NEGOCIO.includes(cls.intent)
  || PRODUCTOS_VALIDOS.includes(cls.product);

const modeOk = gate.mode_ok === true;
const known = gate.known_client === true;
const active = gate.already_active === true;
// Kill switch humano (panel web → W8 → conversations.should_respond). Pesa
// más que cualquier señal de negocio: si Nairobi pausó a Nai en esta
// conversación, no debe reactivarse sola aunque el cliente pida cotización.
const pausedByHuman = gate.should_respond === false;

const should_reply = !pausedByHuman && modeOk && !isIgnore && (active || known || isBusiness);

let gate_reason;
if (pausedByHuman) gate_reason = 'pausado manualmente desde el panel — should_respond=false';
else if (!modeOk) gate_reason = 'modo test: el número no está en test_allowlist';
else if (isIgnore) gate_reason = 'clasificado como ignore';
else if (active) gate_reason = 'conversación ya abierta antes';
else if (known) gate_reason = 'cliente conocido (tiene póliza registrada)';
else if (isBusiness) {
  gate_reason = `señal de negocio (scope=${cls.scope}, intent=${cls.intent}, `
    + `acción=${cls.recommended_action}): abre la conversación`;
} else gate_reason = 'desconocido sin intención de negocio: silencio';

// R021-bis: si isBusiness vino de una señal distinta a scope (product/intent/accion),
// el scope crudo de A0 sigue diciendo 'personal' y el nodo de enrutamiento
// (¿Personal / conversación simple?) solo mira scope — sin este override, el mensaje
// se rescataba de el silencio pero caía en la rama Haiku 'casual', sin guardrails de
// producto/país, y podía improvisar cualquier cosa (visto en vivo: confundió RCV
// venezolano con trámite colombiano). Se corrige el campo en la fuente, una sola vez,
// para que todo lo que venga después (enrutamiento, panel, filtros) vea la verdad.
const scopeFinal = isBusiness ? 'business' : cls.scope;

return [{ json: { ...cls, ...gate, scope: scopeFinal, should_reply, gate_reason } }];

// A0 no pudo devolver el JSON exigido por el esquema (falla real y esperable de
// LLMs contra un schema estricto — no es un bug, es un caso a manejar).
// Ver R016: sin esto, el mensaje del cliente se perdía en silencio para siempre.
// Salida segura: se trata como caso ambiguo y se escala a un humano, nunca se descarta.
const entrada = $('Entrada desde W1').item.json;
return [{
  json: {
    scope: 'unclear',
    intent: 'other',
    product: 'desconocido',
    confidence: 0,
    urgency: 'normal',
    sentiment: 'neutral',
    requires_human: true,
    recommended_action: 'human_required',
    escalation_reason: 'fallo_clasificador',
    extracted_entities: {},
    reasoning: 'El clasificador no devolvió un formato válido; se escala por seguridad.',
  },
}];

parameters.query:
insert into public.messages (conversation_id, contact_id, direction, message_type, message_text, metadata, ai_processed)
values ($1, $2, 'outbound', 'chat', $3, $4::jsonb, true)
returning id;
